SPEC.B1=function(p){
  var s=[bg(C.sage)].concat(chrome(p),[T('How we partner',{x:7.5,y:11.5,w:60,h:7,s:4.6,b:true,tight:true})]);
  var d=[{i:'semilla.svg',h:'Product Development',p:'A dedicated team owns the full lifecycle — discovery, prototyping, MVP and scaling.',l:0},
         {i:'chat-ia.svg',h:'Team Extension',p:'We split responsibilities inside your product process — embedded, not outsourced.',l:1},
         {i:'grafico.svg',h:'Staff Augmentation',p:'Senior talent on your products, under your processes and daily management.',l:0}];
  d.forEach(function(c,i){var x=7.5+i*29,y=21,w=27,h=27;
    s.push(card(x,y,w,h,C.w,C.hair));
    s=s.concat(iconDot(x+2.2,y+2.2,4.4,c.i,c.l));
    s.push(T(c.h,{x:x+2.2,y:y+8.4,w:w-4.4,h:5,s:2.1,b:true,tight:true,lh:1.05}));
    s.push(T(c.p,{x:x+2.2,y:y+13.6,w:w-4.4,h:9,s:1.4,c:C.g600,lh:1.35}));
    s.push(T('Learn more ↗',{x:x+2.2,y:y+h-4,w:w-4.4,h:2.6,s:1.4,b:true}));});
  return s;};

SPEC.B2=function(p){
  var s=[bg(C.w)].concat(chrome(p),[T('Engagement models',{x:7.5,y:11.5,w:70,h:7,s:4.4,b:true,tight:true})]);
  var d=[{h:'Product Development',a:'How it works: we assemble every role needed and own the process end to end.',b:'Best for: building a product from discovery to launch.',f:'Fixed scope · milestone billing',dk:0},
         {h:'Team Extension',a:'How it works: shared responsibilities inside your product development process.',b:'Best for: scaling an existing team with domain fluency in agriculture.',f:'Monthly per role · 3-month cycles',dk:1},
         {h:'Staff Augmentation',a:'How it works: we provide the talent; you keep your processes and management.',b:'Best for: filling senior roles fast, without hiring overhead.',f:'Monthly per role · your PM',dk:0}];
  d.forEach(function(c,i){var x=7.5+i*29,y=20.5,w=27,h=28.5;
    s.push(card(x,y,w,h,c.dk?C.g900:C.sage,null));
    s.push(T(c.h,{x:x+2.2,y:y+2.2,w:w-4.4,h:5,s:2.1,b:true,tight:true,c:c.dk?C.cr50:C.ink,lh:1.05}));
    s.push(T(c.a,{x:x+2.2,y:y+8,w:w-4.4,h:8,s:1.4,c:c.dk?C.cr200:C.g600,lh:1.35}));
    s.push(T(c.b,{x:x+2.2,y:y+15.5,w:w-4.4,h:7,s:1.4,c:c.dk?C.cr200:C.g600,lh:1.35}));
    s.push(R({x:x+2.2,y:y+h-6,w:w-4.4,h:.1,fill:c.dk?C.g700:C.hair}));
    s.push(T(c.f,{x:x+2.2,y:y+h-4.6,w:w-4.4,h:3,s:1.5,b:true,c:c.dk?C.lime:C.ink}));});
  return s;};

SPEC.B3=function(p){
  var s=[bg(C.sage)].concat(chrome(p),[T('What the pod covers',{x:7.5,y:11.5,w:70,h:7,s:4.4,b:true,tight:true})]);
  var d=[['escaneo.svg','Discovery','Field immersion with growers and agronomists.',0],
         ['lote.svg','Product design','Flows built for gloves, dust and low signal.',0],
         ['chat-ia.svg','Data & AI','Models and copilots on agronomic data.',1],
         ['satelite.svg','Platform engineering','APIs, pipelines and cloud that hold a season.',0],
         ['hoja.svg','Agronomy','Agronomists in the pod, not on call.',0],
         ['tractor.svg','Field validation','Every release tested on real operations.',0]];
  d.forEach(function(c,i){var col=i%3,row=Math.floor(i/3),x=7.5+col*29.5,y=21+row*13.5;
    s=s.concat(iconDot(x,y,3.6,c[0],c[3]));
    s.push(T(c[1],{x:x+5,y:y+.2,w:23,h:3,s:1.75,b:true,tight:true}));
    s.push(T(c[2],{x:x+5,y:y+3.4,w:23,h:6,s:1.45,c:C.g600,lh:1.3}));});
  return s;};

